    static D2DrawFloorStrc D2DrawFloorStrc_007c8a28 = {}; D2_STATIC_GUARD(D2DrawFloorStrc_007c8a28, "D2Client::GAME::Draw::dFloorDraw::D2DrawFloorStrc_007c8a28");

